import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Audio } from "remotion";

export const MyAnimation = ({ audioUrl }: { audioUrl?: string }) => {
  /*
   * Dokumentari lakaran vintaj tentang asal usul wang kertas Dinasti Song (jiaozi).
   * Kamera merentas satu buku lakaran perkamen yang berterusan: syiling tembaga, syiling besi Sichuan,
   * resit pedagang Chengdu, jiaozi rasmi 1023, blok cetakan dan neraca. Ia berakhir dengan tarikan mundur yang mendedahkan seluruh buku.
   * Durasi yang dirancang: 960 bingkai pada 30fps.
   */
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const VOICEOVER_SCRIPT =
    "A thousand years ago in China, money meant metal coins strung on cords, and it was heavy. In Sichuan, the coins were iron, far too heavy for big trades. So sixteen merchant houses in Chengdu began issuing paper receipts for stored coins. In ten twenty-three, the Song government took over, and jiaozi was born, the world's first official paper money. Printed from woodblocks, stamped with red seals, and accepted because it was trusted. Today, money keeps getting lighter, because its true value is trust.";

  // ---------- WARNA ----------
  const COLOR_PAPER = "#f5ebe0";
  const COLOR_PAPER_LIGHT = "#fbf4ea";
  const COLOR_INK = "#3b2a1e";
  const COLOR_IRON = "#4a3f38";
  const COLOR_RUST = "#9a3412";
  const COLOR_SEPIA = "#8a6a4a";

  // ---------- FON ----------
  const FONT_SERIF = "'Playfair Display', 'Cormorant Garamond', Georgia, serif";
  const FONT_SANS = "Inter, sans-serif";
  const FONT_HAND = "'Caveat', 'Segoe Script', 'Brush Script MT', cursive";

  // ---------- SUSUN ATUR & MASA ----------
  const STAGE_W = 1920;
  const STAGE_H = 1080;
  const SCENE_LEN = 150;
  const WORD_STAGGER = 4;
  const TEXT_IN = 54;
  const TEXT_OUT = 104;
  const DUST_COUNT = 30;
  const GRAIN_OPACITY = 0.14;
  const SCENES = [
    { cx: 960, cy: 540, ax: 640, ay: 600 },
    { cx: 3000, cy: 760, ax: 2780, ay: 800 },
    { cx: 5000, cy: 420, ax: 4600, ay: 460 },
    { cx: 5200, cy: 2500, ax: 4890, ay: 2500 },
    { cx: 3100, cy: 2800, ax: 2650, ay: 2900 },
    { cx: 1000, cy: 2600, ax: 640, ay: 2700 },
  ];
  const OVERVIEW = { x: 3150, y: 1600, z: 0.29 };
  const FINAL_CARD_AT = 905;

  // ---------- TEKS ----------
  const T0_TITLE = [["Once,", "money"], ["was", "heavy"]];
  const T0_HL = "heavy";
  const T0_KICKER = "CHINA · 10TH CENTURY";
  const T0_NOTE = "strung on cords";
  const T1_TITLE = [["The", "burden"], ["of", "iron"]];
  const T1_HL = "iron";
  const T1_LABEL = "IRON COINS · SICHUAN";
  const T2_TITLE = [["Receipts", "replace"], ["coins"]];
  const T2_HL = "Receipts";
  const T2_KICKER = "CHENGDU · EARLY 11TH CENTURY";
  const T2_NOTE = "16 Chengdu merchant houses";
  const T3_TITLE = [["World's", "first"], ["paper", "money"]];
  const T3_HL = "first";
  const T3_LABEL = "JIAOZI · SONG GOVERNMENT";
  const T3_STAMP = "1023";
  const T3_STAMP_SUB = "OFFICIAL";
  const T4_TITLE = [["Printed,", "sealed,"], ["trusted"]];
  const T4_HL = "trusted";
  const T4_LABEL = "WOODBLOCK PRINTING";
  const T5_TITLE = [["Its", "value"], ["is", "trust"]];
  const T5_HL = "trust";
  const T5_LABEL = "FROM METAL TO TRUST";
  const FINAL_TITLE = "Jiaozi";
  const FINAL_SUB = "SONG DYNASTY · 1023";

  // ---------- PEMBANTU ----------
  const CL = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
  const prog = (f: number, s: number, d: number) => interpolate(f, [s, s + d], [0, 1], CL);
  const sub = (p: number, a: number, b: number) => Math.min(1, Math.max(0, (p - a) / (b - a)));
  const easeIO = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
  const pop = (f: number, s: number, damping = 12) =>
    spring({ frame: Math.max(0, f - s), fps, config: { damping, stiffness: 140, mass: 0.8 } });
  const circ = (cx: number, cy: number, r: number) =>
    `M ${cx - r} ${cy} a ${r} ${r} 0 1 0 ${r * 2} 0 a ${r} ${r} 0 1 0 ${-r * 2} 0`;
  const rectD = (x: number, y: number, x2: number, y2: number) => `M ${x} ${y} H ${x2} V ${y2} H ${x} Z`;

  const ink = (key: string, d: string, p: number, w = 2.4, color = COLOR_INK, op = 1) => (
    <path
      key={key}
      d={d}
      pathLength={1}
      fill="none"
      stroke={color}
      strokeWidth={w}
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeDasharray="1 1"
      strokeDashoffset={1 - p}
      opacity={p > 0.002 ? op : 0}
    />
  );

  const GLYPH = [
    "M -1 -0.7 L 1 -0.7",
    "M 0 -1 L 0 1",
    "M -0.8 0.15 L 0.8 0.15",
    "M -0.9 1 L -0.15 0.35",
    "M 0.15 0.35 L 0.9 1",
    "M -1 -0.2 L -0.35 -0.2 L -0.35 0.85",
    "M 0.4 -1 L 0.4 -0.1 L 1 -0.1",
    "M -0.65 0.75 L 0.65 0.75",
  ];
  const glyph = (key: string, x: number, y: number, s: number, p: number, seed: number, color = COLOR_INK) => (
    <g key={key} transform={`translate(${x} ${y}) scale(${s})`}>
      {[0, 1, 2].map((k) =>
        ink(`${key}-${k}`, GLYPH[(seed * 3 + k * 5 + (seed % 3)) % GLYPH.length], sub(p, k / 3, (k + 1) / 3), 2.2 / s, color)
      )}
    </g>
  );

  const coin = (key: string, cx: number, cy: number, r: number, p: number, color = COLOR_INK, ticks = 14) => {
    const h = r * 0.24;
    const els: React.ReactElement[] = [];
    els.push(<circle key={key + "f"} cx={cx} cy={cy} r={r} fill={COLOR_PAPER_LIGHT} opacity={sub(p, 0.1, 0.4)} />);
    els.push(ink(key + "o", circ(cx, cy, r), sub(p, 0, 0.35), 2.6, color));
    els.push(ink(key + "i", circ(cx, cy, r * 0.86), sub(p, 0.15, 0.45), 1.4, color));
    els.push(ink(key + "h", `M ${cx - h} ${cy - h} L ${cx + h} ${cy - h} L ${cx + h} ${cy + h} L ${cx - h} ${cy + h} Z`, sub(p, 0.3, 0.55), 2.2, color));
    [[0, -1], [1, 0], [0, 1], [-1, 0]].forEach(([dx, dy], k) => {
      const gx = cx + dx * r * 0.56;
      const gy = cy + dy * r * 0.56;
      const s = r * 0.13;
      els.push(
        ink(`${key}g${k}`, `M ${gx - s} ${gy - s * 0.6} L ${gx + s} ${gy - s * 0.6} M ${gx} ${gy - s} L ${gx} ${gy + s} M ${gx - s * 0.8} ${gy + s * 0.5} L ${gx + s * 0.8} ${gy + s * 0.9}`, sub(p, 0.45 + k * 0.07, 0.68 + k * 0.07), 1.6, color)
      );
    });
    for (let k = 0; k < ticks; k++) {
      const a = ((10 + k * (126 / ticks)) * Math.PI) / 180;
      els.push(
        ink(`${key}t${k}`, `M ${cx + Math.cos(a) * r * 0.88} ${cy + Math.sin(a) * r * 0.88} L ${cx + Math.cos(a) * r * 0.98} ${cy + Math.sin(a) * r * 0.98}`, sub(p, 0.6 + k * 0.02, 0.75 + k * 0.02), 1.2, color, 0.8)
      );
    }
    return <g key={key}>{els}</g>;
  };

  const seal = (key: string, x: number, y: number, size: number, f: number, start: number, rot: number) => {
    const s = pop(f, start, 11);
    const sc = interpolate(s, [0, 1], [2.3, 1], CL);
    const op = prog(f, start, 4) * 0.88;
    const h = size / 2;
    return (
      <g key={key} transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`} opacity={op}>
        <rect x={-h} y={-h} width={size} height={size} rx={size * 0.08} fill={COLOR_RUST} />
        <path d={`M ${-h * 0.6} ${-h * 0.4} H ${h * 0.6} M 0 ${-h * 0.7} V ${h * 0.7} M ${-h * 0.6} ${h * 0.35} H ${h * 0.6} M ${-h * 0.75} ${-h * 0.75} H ${h * 0.75} V ${h * 0.75} H ${-h * 0.75} Z`} fill="none" stroke={COLOR_PAPER} strokeWidth={size * 0.06} />
      </g>
    );
  };

  const corner = (key: string, x: number, y: number, sx: number, sy: number, p: number, color = COLOR_INK) => (
    <g key={key} transform={`translate(${x} ${y}) scale(${sx} ${sy})`}>
      {ink(key + "c", "M 0 0 q 18 0 18 18 q 0 12 -12 12 q -9 0 -9 -9 q 0 -6 6 -6", p, 1.8, color)}
    </g>
  );

  // ---------- KAMERA ----------
  type KF = [number, number, number, number];
  const KEYS: KF[] = [];
  SCENES.forEach((sc, i) => {
    const b = i * SCENE_LEN;
    KEYS.push([b, sc.ax, sc.ay, 1.42], [b + 16, sc.ax, sc.ay, 1.34], [b + 50, sc.cx, sc.cy, 1]);
    if (i < SCENES.length - 1) KEYS.push([b + 112, sc.cx, sc.cy, 1.045]);
    else
      KEYS.push(
        [b + 108, sc.cx, sc.cy, 1.04],
        [b + 162, OVERVIEW.x, OVERVIEW.y, OVERVIEW.z],
        [b + 210, OVERVIEW.x, OVERVIEW.y, OVERVIEW.z * 1.04]
      );
  });
  let cam: KF = KEYS[KEYS.length - 1];
  if (frame <= KEYS[0][0]) cam = KEYS[0];
  else {
    for (let k = 0; k < KEYS.length - 1; k++) {
      const a = KEYS[k];
      const c = KEYS[k + 1];
      if (frame >= a[0] && frame <= c[0]) {
        const t = easeIO((frame - a[0]) / (c[0] - a[0]));
        cam = [frame, a[1] + (c[1] - a[1]) * t, a[2] + (c[2] - a[2]) * t, a[3] + (c[3] - a[3]) * t];
        break;
      }
    }
  }
  const camZ = cam[3] * (1 + 0.005 * Math.sin(frame * 0.05));
  const camTx = STAGE_W / 2 - cam[1] * camZ;
  const camTy = STAGE_H / 2 - cam[2] * camZ;
  const stageScale = Math.min(width / STAGE_W, height / STAGE_H);

  // ---------- TEKS KINETIK ----------
  const renderTitle = (key: string, f: number, start: number, exit: number | null, lines: string[][], hl: string, x: number, y: number, size: number) => {
    let idx = 0;
    const nWords = lines.flat().length;
    const e = exit == null ? 0 : prog(f, exit, 10);
    const hlP = prog(f, start + nWords * WORD_STAGGER + 10, 16);
    return (
      <div key={key} style={{ position: "absolute", left: x, top: y, fontFamily: FONT_SERIF, fontSize: size, fontWeight: 600, color: COLOR_INK, lineHeight: 1.12, letterSpacing: "-0.01em", whiteSpace: "nowrap", opacity: 1 - e, transform: `translateY(${-50 * e}px)`, filter: e > 0 ? `blur(${e * 8}px)` : undefined }}>
        {lines.map((ln, li) => (
          <div key={li}>
            {ln.map((w) => {
              const i = idx++;
              const s = pop(f, start + i * WORD_STAGGER, 14);
              const isHl = w === hl;
              return (
                <span key={w + i} style={{ display: "inline-block", position: "relative", marginRight: "0.26em", opacity: Math.min(1, s * 1.4), transform: `translateY(${(1 - s) * 55}%) scaleY(${1 + (1 - s) * 0.3})`, transformOrigin: "50% 100%", color: isHl ? COLOR_RUST : COLOR_INK, fontStyle: isHl ? "italic" : "normal" }}>
                  {w}
                  {isHl && (
                    <svg style={{ position: "absolute", left: "-4%", bottom: "-0.12em", width: "108%", height: "0.3em", overflow: "visible" }} viewBox="0 0 100 10" preserveAspectRatio="none">
                      <path d="M 2 6 C 20 2, 40 9, 60 5 S 90 3, 98 6" pathLength={1} fill="none" stroke={COLOR_RUST} strokeWidth={4} strokeLinecap="round" strokeDasharray="1 1" strokeDashoffset={1 - hlP} vectorEffect="non-scaling-stroke" opacity={hlP > 0 ? 1 : 0} />
                    </svg>
                  )}
                </span>
              );
            })}
          </div>
        ))}
      </div>
    );
  };

  const renderLabel = (key: string, f: number, start: number, exit: number | null, text: string, x: number, y: number, color = COLOR_SEPIA) => {
    const p = Math.min(1, pop(f, start, 16));
    const e = exit == null ? 0 : prog(f, exit, 10);
    return (
      <div key={key} style={{ position: "absolute", left: x, top: y, fontFamily: FONT_SANS, fontSize: 34, fontWeight: 600, letterSpacing: "0.2em", color, whiteSpace: "nowrap", opacity: p * (1 - e), transform: `translateX(${(1 - p) * -40}px) translateY(${-30 * e}px)` }}>
        <span style={{ display: "inline-block", width: 56, height: 3, background: color, verticalAlign: "middle", marginRight: 18, transform: `scaleX(${p})`, transformOrigin: "0 50%" }} />
        {text}
      </div>
    );
  };

  const renderNote = (key: string, f: number, start: number, exit: number | null, text: string, x: number, y: number, size = 56, rot = -3) => {
    const p = prog(f, start, 24);
    const e = exit == null ? 0 : prog(f, exit, 10);
    return (
      <div key={key} style={{ position: "absolute", left: x, top: y, fontFamily: FONT_HAND, fontSize: size, color: COLOR_RUST, whiteSpace: "nowrap", transform: `rotate(${rot}deg) translateY(${-40 * e}px)`, clipPath: `inset(-30% ${100 - p * 100}% -30% -5%)`, opacity: 1 - e }}>
        {text}
      </div>
    );
  };

  const renderStamp = (key: string, f: number, start: number, x: number, y: number, w: number, h: number, main: string, small: string, rot: number) => {
    const s = pop(f, start, 11);
    const sc = interpolate(s, [0, 1], [2.4, 1], CL);
    return (
      <div key={key} style={{ position: "absolute", left: x, top: y, width: w, height: h, border: `6px solid ${COLOR_RUST}`, boxShadow: `inset 0 0 0 8px ${COLOR_PAPER}, inset 0 0 0 12px ${COLOR_RUST}`, color: COLOR_RUST, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", transform: `rotate(${rot}deg) scale(${sc})`, opacity: prog(f, start, 4) * 0.9, mixBlendMode: "multiply", borderRadius: 10 }}>
        <div style={{ fontFamily: FONT_SERIF, fontSize: 100, fontWeight: 700, lineHeight: 1 }}>{main}</div>
        <div style={{ fontFamily: FONT_SANS, fontSize: 30, fontWeight: 700, letterSpacing: "0.3em", marginTop: 6 }}>{small}</div>
      </div>
    );
  };

  // ---------- BINGKAI TEMPATAN SETIAP ADEGAN ----------
  const lf = SCENES.map((_, i) => frame - i * SCENE_LEN);

  // ===== ADEGAN 0: rentetan syiling tembaga =====
  const f0 = lf[0];
  const pString = prog(f0, 0, 64);
  const scene0: React.ReactElement[] = [];
  scene0.push(ink("s0cord", "M 606 170 C 600 400, 640 650, 620 870", sub(pString, 0, 0.25), 3, COLOR_SEPIA));
  scene0.push(ink("s0knot", "M 606 170 c -30 -10 -30 -50 0 -50 c 30 0 30 40 0 50 c -20 20 -40 30 -55 20", sub(pString, 0, 0.2), 2.4, COLOR_SEPIA));
  for (let k = 0; k < 7; k++) {
    scene0.push(coin(`s0c${k}`, 610 + Math.sin(k * 0.9) * 14, 300 + k * 80, 74, sub(pString, 0.08 + k * 0.09, 0.08 + k * 0.09 + 0.38)));
  }
  for (let k = 0; k < 7; k++) {
    scene0.push(ink(`s0tas${k}`, `M 620 860 Q ${600 + k * 7} 920 ${575 + k * 15} 980`, sub(pString, 0.8 + k * 0.02, 1), 1.6, COLOR_RUST));
  }
  const pArrow0 = prog(f0, 22, 24);
  scene0.push(ink("s0arr", "M 800 400 C 812 520, 790 640, 800 760", sub(pArrow0, 0, 0.7), 3.4, COLOR_RUST));
  scene0.push(ink("s0arrh", "M 770 725 L 800 765 L 832 726", sub(pArrow0, 0.7, 1), 3.4, COLOR_RUST));

  // ===== ADEGAN 1: grid syiling besi + kandar =====
  const f1 = lf[1];
  const scene1: React.ReactElement[] = [];
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 6; c++) {
      const n = r * 6 + c;
      const st = -14 + n * 2.2;
      const x = 2467.5 + c * 125;
      const y = 612.5 + r * 125;
      const s = interpolate(pop(f1, st, 10), [0, 1], [0.4, 1], CL);
      scene1.push(
        <g key={`s1g${n}`} transform={`translate(${x} ${y}) scale(${s}) translate(${-x} ${-y})`} opacity={prog(f1, st, 3)}>
          {coin(`s1c${n}`, x, y, 54, prog(f1, st, 22), COLOR_IRON, 6)}
        </g>
      );
    }
  }
  const pPole = prog(f1, 24, 50);
  scene1.push(ink("s1pole", "M 3290 820 Q 3555 885 3820 820", sub(pPole, 0, 0.25), 6, COLOR_INK));
  [3320, 3790].forEach((px, b) => {
    const bx = px - 50;
    scene1.push(ink(`s1r${b}a`, `M ${px} 830 L ${bx} 960`, sub(pPole, 0.2, 0.35), 2, COLOR_INK));
    scene1.push(ink(`s1r${b}b`, `M ${px} 830 L ${bx + 100} 960`, sub(pPole, 0.22, 0.37), 2, COLOR_INK));
    scene1.push(ink(`s1bk${b}`, `M ${bx - 20} 960 L ${bx + 120} 960 L ${bx + 95} 1080 L ${bx + 5} 1080 Z`, sub(pPole, 0.35, 0.6), 2.6, COLOR_INK));
    for (let k = 0; k < 4; k++) {
      const yy = 985 + k * 24;
      const inset = 4 + k * 5;
      scene1.push(ink(`s1w${b}${k}`, `M ${bx - 20 + inset} ${yy} L ${bx + 120 - inset} ${yy}`, sub(pPole, 0.6 + k * 0.05, 0.75 + k * 0.05), 1.3, COLOR_INK, 0.8));
    }
    for (let k = 0; k < 3; k++) {
      scene1.push(ink(`s1top${b}${k}`, `M ${bx + 5 + k * 35} 960 a 18 10 0 0 1 36 0`, sub(pPole, 0.8 + k * 0.05, 1), 2, COLOR_IRON));
    }
  });

  // ===== ADEGAN 2: resit pedagang =====
  const f2 = lf[2];
  const scene2: React.ReactElement[] = [];
  const pBack = prog(f2, -14, 40);
  scene2.push(
    <g key="s2back" transform="rotate(5 4640 470)">
      <rect x={4420} y={180} width={400} height={580} fill={COLOR_PAPER_LIGHT} opacity={sub(pBack, 0, 0.3)} />
      {ink("s2bb", rectD(4420, 180, 4820, 760), pBack, 2.2, COLOR_SEPIA)}
      {[0, 1, 2, 3].map((c) => ink(`s2bl${c}`, `M ${4740 - c * 80} 240 V 700`, sub(pBack, 0.4 + c * 0.1, 0.7 + c * 0.1), 1.2, COLOR_SEPIA, 0.6))}
    </g>
  );
  const pDoc = prog(f2, -6, 78);
  const docGlyphs: React.ReactElement[] = [];
  for (let c = 0; c < 5; c++) {
    for (let r = 0; r < 8; r++) {
      const a = 0.25 + ((c * 8 + r) / 40) * 0.62;
      docGlyphs.push(glyph(`s2gl${c}${r}`, 4720 - c * 75, 240 + r * 58, 18, sub(pDoc, a, a + 0.06), c * 8 + r));
    }
  }
  scene2.push(
    <g key="s2front" transform="rotate(-4 4590 460)">
      <rect x={4380} y={160} width={410} height={610} fill={COLOR_PAPER_LIGHT} opacity={sub(pDoc, 0, 0.2)} />
      {ink("s2fb", rectD(4380, 160, 4790, 770), sub(pDoc, 0, 0.2), 3, COLOR_INK)}
      {ink("s2fi", rectD(4396, 176, 4774, 754), sub(pDoc, 0.1, 0.25), 1.4, COLOR_INK)}
      {corner("s2k1", 4396, 176, 1, 1, sub(pDoc, 0.2, 0.3))}
      {corner("s2k2", 4774, 176, -1, 1, sub(pDoc, 0.2, 0.3))}
      {corner("s2k3", 4396, 754, 1, -1, sub(pDoc, 0.2, 0.3))}
      {corner("s2k4", 4774, 754, -1, -1, sub(pDoc, 0.2, 0.3))}
      {docGlyphs}
      {seal("s2seal", 4700, 690, 70, f2, 44, 6)}
    </g>
  );
  const pArrow2 = prog(f2, 84, 20);
  scene2.push(ink("s2arr", "M 4950 640 C 4900 600, 4860 590, 4815 600", sub(pArrow2, 0, 0.75), 3, COLOR_RUST));
  scene2.push(ink("s2arrh", "M 4840 580 L 4812 601 L 4842 620", sub(pArrow2, 0.75, 1), 3, COLOR_RUST));

  // ===== ADEGAN 3: jiaozi rasmi =====
  const f3 = lf[3];
  const scene3: React.ReactElement[] = [];
  const pNote = prog(f3, -14, 90);
  scene3.push(<rect key="s3fill" x={4700} y={2070} width={380} height={860} fill={COLOR_PAPER_LIGHT} opacity={sub(pNote, 0, 0.15)} />);
  scene3.push(ink("s3ob", rectD(4700, 2070, 5080, 2930), sub(pNote, 0, 0.15), 4, COLOR_INK));
  scene3.push(ink("s3ib", rectD(4718, 2088, 5062, 2912), sub(pNote, 0.08, 0.2), 1.5, COLOR_INK));
  scene3.push(corner("s3k1", 4718, 2088, 1, 1, sub(pNote, 0.15, 0.25)));
  scene3.push(corner("s3k2", 5062, 2088, -1, 1, sub(pNote, 0.15, 0.25)));
  scene3.push(corner("s3k3", 4718, 2912, 1, -1, sub(pNote, 0.15, 0.25)));
  scene3.push(corner("s3k4", 5062, 2912, -1, -1, sub(pNote, 0.15, 0.25)));
  scene3.push(ink("s3band", "M 4718 2200 H 5062", sub(pNote, 0.2, 0.28), 1.6, COLOR_INK));
  for (let k = 0; k < 4; k++) scene3.push(glyph(`s3tg${k}`, 4775 + k * 77, 2145, 24, sub(pNote, 0.25 + k * 0.04, 0.33 + k * 0.04), k + 11));
  scene3.push(ink("s3roof", "M 4750 2335 Q 4890 2255 5030 2335 M 4750 2335 q -14 -4 -20 -18 M 5030 2335 q 14 -4 20 -18", sub(pNote, 0.4, 0.5), 2.6, COLOR_INK));
  for (let k = 0; k < 8; k++) scene3.push(ink(`s3rh${k}`, `M ${4790 + k * 28} ${2318 - Math.sin((k / 7) * Math.PI) * 30} l 0 18`, sub(pNote, 0.48 + k * 0.01, 0.53 + k * 0.01), 1.2, COLOR_INK, 0.8));
  [4790, 4850, 4930, 4990].forEach((px, k) => scene3.push(ink(`s3pl${k}`, `M ${px} 2340 V 2460`, sub(pNote, 0.5 + k * 0.02, 0.58 + k * 0.02), 2, COLOR_INK)));
