  // ===== ADEGAN 4: blok cetakan + kipas wang =====
  const f4 = lf[4];
  const scene4: React.ReactElement[] = [];
  const pBlock = prog(f4, -14, 70);
  scene4.push(<path key="s4fill" d="M 2380 2800 L 2780 2720 L 2940 2860 L 2940 2960 L 2540 3040 L 2380 2900 Z" fill="#e9d8c2" opacity={sub(pBlock, 0, 0.3)} />);
  scene4.push(ink("s4top", "M 2380 2800 L 2780 2720 L 2940 2860 L 2540 2940 Z", sub(pBlock, 0, 0.25), 2.8, COLOR_INK));
  scene4.push(ink("s4front", "M 2380 2800 L 2380 2900 L 2540 3040 L 2540 2940", sub(pBlock, 0.15, 0.35), 2.8, COLOR_INK));
  scene4.push(ink("s4side", "M 2540 3040 L 2940 2960 L 2940 2860", sub(pBlock, 0.2, 0.4), 2.8, COLOR_INK));
  for (let k = 0; k < 11; k++) {
    const x = 2392 + k * 14;
    const ty = 2800 + (x - 2380) * (140 / 160);
    scene4.push(ink(`s4hf${k}`, `M ${x} ${ty + 6} V ${ty + 94}`, sub(pBlock, 0.4 + k * 0.015, 0.5 + k * 0.015), 1.2, COLOR_INK, 0.75));
  }
  for (let k = 0; k < 18; k++) {
    const x = 2556 + k * 21;
    const ty = 2940 - (x - 2540) * (80 / 400);
    const hLen = k % 2 === 1 ? 60 : 92;
    const yA = ty + 8;
    const yB = ty + hLen;
    const hsStart = 0.45 + k * 0.012;
    const hsEnd = 0.55 + k * 0.012;
    const hsPath = "M " + x + " " + yA + " V " + yB;
    scene4.push(ink("s4hs" + k, hsPath, sub(pBlock, hsStart, hsEnd), 1.2, COLOR_INK, 0.75));
  }
  for (let u = 0; u < 5; u++) for (let v = 0; v < 3; v++) {
    const uu = 0.15 + u * 0.175;
    const vv = 0.22 + v * 0.28;
    const gx = 2380 + uu * 400 + vv * 160;
    const gy = 2800 - uu * 80 + vv * 140;
    scene4.push(glyph(`s4cg${u}${v}`, gx, gy, 12, sub(pBlock, 0.65 + (u * 3 + v) * 0.02, 0.72 + (u * 3 + v) * 0.02), u * 3 + v));
  }
  for (let k = 0; k < 5; k++) {
    const st = 26 + k * 7;
    const s = pop(f4, st, 13);
    const ang = (-28 + k * 14) * Math.min(1, s);
    const sc = interpolate(s, [0, 1], [0.5, 1], CL);
    const pN = prog(f4, st, 22);
    scene4.push(
      <g key={`s4n${k}`} transform={`rotate(${ang} 3580 3170) translate(3580 3170) scale(${sc}) translate(-3580 -3170)`} opacity={prog(f4, st, 4)}>
        <rect x={3505} y={2860} width={150} height={270} fill={COLOR_PAPER_LIGHT} />
        {ink(`s4nb${k}`, rectD(3505, 2860, 3655, 3130), pN, 2.4, COLOR_INK)}
        {ink(`s4ni${k}`, rectD(3515, 2870, 3645, 3120), sub(pN, 0.3, 0.7), 1.2, COLOR_INK)}
        {[0, 1, 2].map((r) => ink(`s4nl${k}${r}`, `M 3530 ${2920 + r * 50} H 3630`, sub(pN, 0.5 + r * 0.1, 0.8 + r * 0.1), 1.4, COLOR_SEPIA))}
        {seal(`s4ns${k}`, 3610, 3085, 34, f4, st + 12, 4)}
      </g>
    );
