  for (let k = 0; k < 10; k++) scene5.push(ink(`s5bh${k}`, `M ${525 + k * 24} 2995 L ${545 + k * 22} 2965`, sub(pBal, 0.3 + k * 0.02, 0.4 + k * 0.02), 1.2, COLOR_INK, 0.7));
  scene5.push(ink("s5fin", circ(PX, PY - 22, 13), sub(pBal, 0.2, 0.3), 2.2, COLOR_INK));
  scene5.push(ink("s5beam", `M ${Lx} ${Ly} L ${Rx} ${Ry}`, sub(pBal, 0.25, 0.45), 4.5, COLOR_INK));
  [[Lx, Ly, "l"], [Rx, Ry, "r"]].forEach(([x, y, n]) => {
