  });
  const pLoad = prog(f5, 18, 30);
  scene5.push(coin("s5c1", Lx - 42, Ly + 178, 28, sub(pLoad, 0, 0.5), COLOR_INK, 5));
  scene5.push(coin("s5c2", Lx + 18, Ly + 180, 28, sub(pLoad, 0.15, 0.65), COLOR_INK, 5));
  scene5.push(coin("s5c3", Lx - 12, Ly + 150, 28, sub(pLoad, 0.3, 0.8), COLOR_INK, 5));
  const floatY = Math.sin(frame * 0.08) * 6 * Math.min(1, pLoad);
  scene5.push(
