  );

  // ===== LALUAN PERJALANAN DI ANTARA ADEGAN =====
  const ROUTES = [
    "M 1720 700 C 1950 640, 2100 900, 2330 780",
    "M 3980 700 C 4100 620, 4150 460, 4300 400",
    "M 5500 960 C 5800 1300, 5500 1700, 5700 2000",
    "M 4560 2620 C 4400 2700, 4200 2600, 4000 2750",
