            const s = sp(f5, 70 + i * 15, 13);
            const fx = 1380 + i * 70;
            const fy = 250 + i * 60;
            const x = 1100 + (fx - 1100) * s;
            const y = 400 + (fy - 400) * s;
            const sealS = sp(f5, 118 + i * 13, 11, 220);
            return (
              <g key={`sh${i}`} transform={`translate(${x} ${y}) rotate(${(-6 + i * 5) * s})`} opacity={Math.min(1, s * 1.6)}>
                <rect x={0} y={0} width={240} height={340} fill={COLOR_PAPER_LIGHT} />
                <rect x={14} y={14} width={212} height={312} strokeWidth={1.4} />
                {[70, 110, 150, 190].map((ly, k) => (
                  <line key={`sl${k}`} x1={36} y1={ly} x2={k % 2 ? 160 : 200} y2={ly} strokeWidth={2} />
                ))}
                <g transform={`translate(176 270) scale(${interpolate(sealS, [0, 1], [2.4, 1])})`} opacity={f5 >= 118 + i * 13 ? 0.88 : 0}>
                  <rect x={-34} y={-34} width={68} height={68} fill={SHEET_COLORS[i]} stroke="none" />
                  <rect x={-24} y={-24} width={48} height={48} stroke={COLOR_PAPER_LIGHT} strokeWidth={2} />
                </g>
              </g>
            );
          })}
        </g>
      )}
      {titleBlock(f5, TEXT_AT, S5_TITLE, S5_SUB, S5_LABEL, 96, 64, 3)}
    </>
  ));

  // ----- Adegan 6: terlalu banyak dicetak, nilai merosot -----
  const f6 = frame - SCENE_STARTS[5];
  const stackCount = Math.floor(interpolate(f6, [30, 140], [0, 24], CLAMP));
  const scene6 = sceneBox(5, (
    <>
      {svgWrap(
        <g transform="translate(80 0)">
          {Array.from({ length: 24 }, (_, i) => {
            if (i >= stackCount) return null;
            const appear = 30 + (i / 24) * 110;
            const s = sp(f6, appear, 12, 180);
            return (
              <g key={`st${i}`} transform={`translate(${Math.sin(i * 1.7) * 9} ${(1 - s) * -50})`} opacity={Math.min(1, s * 2)}>
                <rect x={1000} y={862 - i * 20} width={220} height={16} fill={COLOR_PAPER_LIGHT} strokeWidth={2} />
                <rect x={1180} y={865 - i * 20} width={14} height={10} fill={COLOR_RUST} stroke="none" opacity={0.8} />
              </g>
            );
          })}
          <path d="M1320 380 V860 H1640" pathLength={1} style={st(dp(f6, 40, 26))} />
          {hatch("ax", 1320, 862, 320, 14, 18, f6, 50, 10, -10)}
          <path d="M1330 420 L1380 452 L1420 440 L1470 560 L1510 598 L1560 760 L1610 820" pathLength={1}
            stroke={COLOR_RUST} strokeWidth={5} style={st(dp(f6, 66, 60))} />
          <path d="M1588 806 L1612 822 L1612 794" pathLength={1} stroke={COLOR_RUST} strokeWidth={5} style={st(dp(f6, 124, 8))} />
          <text x={1340} y={360} fontFamily={FONT_SERIF} fontStyle="italic" fontSize={48} fill={COLOR_INK} stroke="none"
            opacity={dp(f6, 60, 14)}>nilai</text>
        </g>
      )}
      {titleBlock(f6, TEXT_AT, S6_TITLE, S6_SUB, S6_LABEL, 88, 72, 1)}
    </>
  ));

  // ----- Lapisan skrin -----
  const borderP = dp(frame, 0, 50);
  const endP = dp(frame, END_AT, 26);
  const dust = Array.from({ length: 36 }, (_, i) => {
    const speed = 0.35 + (i % 5) * 0.14;
    const x = ((i * 523) % 1920) + Math.sin(frame / 40 + i) * 14;
    const y = 1100 - ((frame * speed + i * 97) % 1200);
    const size = 2 + (i % 4);
    return (
      <div key={`d${i}`} style={{ position: "absolute", left: x, top: y, width: size, height: size, borderRadius: "50%",
        background: "#8a6a4a", opacity: 0.18 + (i % 3) * 0.06 }} />
    );
  });

  return (
    <AbsoluteFill style={{ backgroundColor: COLOR_PAPER, overflow: "hidden" }}>
      {audioUrl && <Audio src={audioUrl} />}
      <div style={{ position: "absolute", left: "50%", top: "50%", width: STAGE_W, height: STAGE_H,
        transform: `translate(-50%,-50%) scale(${stageScale})`, overflow: "hidden", backgroundColor: COLOR_PAPER }}>
        {/* Dunia / rig kamera */}
        <div style={{ position: "absolute", left: 0, top: 0, width: STAGE_W, height: STAGE_H, transformOrigin: "0 0", transform: worldTransform }}>
          <div style={{ position: "absolute", left: -2000, top: -2000, width: 10500, height: 7500, backgroundColor: COLOR_PAPER,
            backgroundImage:
              "radial-gradient(circle at 18% 22%, rgba(160,110,60,0.13), transparent 18%)," +
              "radial-gradient(circle at 62% 30%, rgba(154,52,18,0.06), transparent 22%)," +
              "radial-gradient(circle at 40% 70%, rgba(140,95,50,0.12), transparent 20%)," +
              "radial-gradient(circle at 80% 65%, rgba(160,110,60,0.10), transparent 24%)," +
              "radial-gradient(circle at 50% 50%, rgba(255,250,240,0.5), transparent 60%)" }} />
          {scene1}
          {scene2}
          {scene3}
          {scene4}
          {scene5}
          {scene6}
        </div>

        {/* Habuk terapung */}
        {dust}

        {/* Bingkai ukiran hiasan */}
        <svg width={STAGE_W} height={STAGE_H} style={{ position: "absolute", left: 0, top: 0 }} fill="none" stroke={COLOR_INK} strokeLinecap="round">
          <rect x={34} y={34} width={1852} height={1012} pathLength={1} strokeWidth={2.4} style={st(borderP, 0.75)} />
          <rect x={48} y={48} width={1824} height={984} pathLength={1} strokeWidth={1} style={st(dp(frame, 10, 50), 0.6)} />
          {[[48, 48], [1872, 48], [48, 1032], [1872, 1032]].map(([x, y], i) => (
            <path key={`cn${i}`} d={`M${x} ${y - 18} L${x + 18} ${y} L${x} ${y + 18} L${x - 18} ${y} Z`} pathLength={1}
              stroke={COLOR_RUST} strokeWidth={2.4} style={st(dp(frame, 30 + i * 5, 20))} />
          ))}
        </svg>

        {/* Penutup */}
        <div style={{ position: "absolute", inset: 0, opacity: endP,
          background: `radial-gradient(48% 42% at 50% 50%, rgba(245,235,224,0.96), rgba(245,235,224,0.75) 60%, rgba(245,235,224,0) 100%)` }} />
        <div style={{ position: "absolute", left: 0, right: 0, top: 380, display: "flex", flexDirection: "column", alignItems: "center" }}>
          {frame >= END_AT && words(END_TITLE, frame, END_AT + 8, 96, { accent: 4, stagger: 5 })}
          {frame >= END_AT && (
            <div style={{ marginTop: 14 }}>{words(END_SUB, frame, END_AT + 34, 46, { italic: true, weight: 500, stagger: 3 })}</div>
          )}
          <div style={{ marginTop: 40, fontFamily: FONT_LABEL, fontSize: 30, letterSpacing: "0.2em", textTransform: "uppercase",
            color: COLOR_INK, opacity: 0.65 * dp(frame, END_AT + 50, 16) }}>{END_CREDIT}</div>
        </div>

        {/* Bijian kertas & vignet */}
        <svg width={STAGE_W} height={STAGE_H} style={{ position: "absolute", left: 0, top: 0, mixBlendMode: "multiply", opacity: 0.14, pointerEvents: "none" }}>
          <filter id="pgrain">
            <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={Math.floor(frame / 3) % 10} />
            <feColorMatrix type="saturate" values="0" />
          </filter>
          <rect width="100%" height="100%" filter="url(#pgrain)" />
        </svg>
        <div style={{ position: "absolute", inset: 0, pointerEvents: "none",
          background: "radial-gradient(ellipse at 50% 50%, rgba(0,0,0,0) 55%, rgba(90,58,28,0.32) 100%)" }} />
      </div>
    </AbsoluteFill>
  );
};
